AND p.deleted = 0

    AND p.tenant_id = #{query.tenantId}


    AND p.pre_disassembly_state = #{query.preDisassemblyState}


    AND (p.price_passed_state is null or p.price_passed_state =0)


    AND p.price_passed_state = 1


    AND p.disassembly_finished = #{query.disassemblyFinished}



    AND p.push_plm_status = #{query.pushPlmStatus}


    AND p.designer_id in

        #{designerId}



    AND p.design_code REGEXP
    CONCAT_WS('|',

        '${item}'

    )


    AND p.style_code REGEXP
    CONCAT_WS('|',

        '${item}'

    )



    AND p.category_name in

        #{categoryName}




    AND ds.wave_band_code in

        #{waveBandCode}



    AND p.designer_id in

        #{item}



    AND ds.store_id in

        #{storeId}



    AND ds.style_label_code in

        #{styleLabelCode}



    AND ds.style_level_code in

        #{styleLevelCode}



    and p.spu_created_time  >=  #{query.spuCreatedTimeStart,jdbcType=TIMESTAMP}


    and p.spu_created_time  <=  #{query.spuCreatedTimeEnd,jdbcType=TIMESTAMP}


    and p.created_time  >=  #{query.skcCreatedTimeStart,jdbcType=TIMESTAMP}


    and p.created_time  <=  #{query.skcCreatedTimeEnd,jdbcType=TIMESTAMP}




            AND ds.image_update_status IS NULL


            AND ds.image_update_status = #{query.imageUpdateStatus}





    AND p.prototype_status = #{query.prototypeStatus}


    AND p.is_make_more = #{query.isMakeMore}


    AND p.is_canceled = #{query.isCanceled}


    and p.is_on_sale=#{query.isOnSale,jdbcType=INTEGER}


    and p.skc_type=#{query.skcType,jdbcType=INTEGER}


    and p.listing_status=#{query.listingStatus,jdbcType=INTEGER}



    and ( ( pd.check_price_state != 2 or pd.check_price_state is null) and (pd.predict_check_price_status != 2
    or pd.predict_check_price_status is null ))



    and (pd.check_price_state = 2 or pd.predict_check_price_status = 2)

mapper.select:
SELECT p.style_code, p.design_code, ds.category_name, ds.store_name storeName, ds.wave_band_name waveBandName, ds.style_label_name styleLabelName, CASE WHEN p.skc_type = 1 THEN '正常款' WHEN p.skc_type = 2 THEN '复色款' ELSE '数据异常' END skc_type, ds.visual_form_name visualFormName, ds.style_level_name styleLevelName, ds.clothing_style_name clothingStyleName, ds.scene_name sceneName, ds.gala_name galaName, ds.printing_name printingName, ds.weave_mode_name weaveModeName, ds.quality_level_name qualityLevelName, ds.season_name seasonName, p.color, ds.size_standard_name sizeStandardName, ds.pattern_name patternName, ds.elastic_name elasticName, ds.designer_name designerName, p.skc_created_time skcCreatedTime
from prototype p left join prototype_detail pd on p.prototype_id = pd.prototype_id left join design_style ds on p.style_code = ds.style_code
ORDER BY p.created_time DESC, p.prototype_id DESC limit #{query.pageSize}

SELECT pp.prototype_id,pp.design_code FROM prototype pp INNER JOIN design_style dd ON dd.style_code = pp.style_code WHERE pp.deleted = 0 AND dd.message = '导入旧的PLM款式操作'
AND pp.design_code in
#{skcCode}

mapper.update:
UPDATE prototype



WHERE prototype_id = #{prototypeId}
AND deleted = 0

UPDATE prototype

    version = version + 1,


WHERE prototype_id = #{prototypeId}
AND version = #{version}
AND deleted = 0
